before_function:
public void onApplicationEvent(WorkflowTaskFailAlarmEvent event) {
    if (!queue.offer(event.getWorkflowTaskBatchId())) {
        SnailJobLog.LOCAL.warn("Workflow任务执行失败告警队列已满");
    }
}

